import{_ as t,o as a,c as i,ak as o}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"Choose what you use","description":"Pick the capabilities your instance and each project use from the Setup page, and decline the rest so the dashboard stops showing them.","frontmatter":{"title":"Choose what you use","description":"Pick the capabilities your instance and each project use from the Setup page, and decline the rest so the dashboard stops showing them.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/capabilities.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/capabilities.html"}],["meta",{"property":"og:title","content":"Choose what you use | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Pick the capabilities your instance and each project use from the Setup page, and decline the rest so the dashboard stops showing them."}]]},"headers":[],"relativePath":"operate/capabilities.md","filePath":"operate/capabilities.md","lastUpdated":1790979351000}'),s={name:"operate/capabilities.md"};function n(r,e,c,l,h,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="choose-what-you-use" tabindex="-1">Choose what you use <a class="header-anchor" href="#choose-what-you-use" aria-label="Permalink to &quot;Choose what you use&quot;">​</a></h1><p>The <strong>Setup</strong> page (<code>/setup</code>, administrators only) is the permanent home for &quot;how do I connect this, and what else can it do?&quot;. Above the connect steps it asks one coarse question, <em>What do you want Piwi for?</em>, with <strong>See why tests fail</strong> always on and three opt-out groups: <strong>Triage as a team</strong> (notifications, quarantine, pull-request feedback, issue tracking), <strong>Fix faster</strong> (locator healing, auto-heal), and <strong>Let agents in</strong> (AI diagnosis). Below it, a ladder lists every optional capability grouped by state: <strong>Active</strong> (evidence has arrived), <strong>Available</strong> (configured but not used yet), <strong>Not set up</strong>, and a folded <strong>Declined</strong> group.</p><h2 id="declining-a-capability" tabindex="-1">Declining a capability <a class="header-anchor" href="#declining-a-capability" aria-label="Permalink to &quot;Declining a capability&quot;">​</a></h2><p>Not every team uses every capability. Any optional one can be <strong>declined</strong> so the dashboard stops showing it everywhere: the evidence tabs, empty panels, settings page, sidebar entry, project actions and MCP tools it owns all go, rather than lingering half-visible. Decline instance-wide from the Setup ladder (<em>Not for this instance</em>) or the presets, or per project from the <strong>Capabilities</strong> section of the project&#39;s <strong>Settings</strong> tab and the places the capability appears (for example the execution page&#39;s evidence footer, <em>Not for this project</em>). A project override can also <strong>enable</strong> a capability the instance declined.</p><p>Declining is administrator-only and never final: each declined capability keeps a <em>Reconsider</em> link on the Setup ladder that clears the decision, and because data always wins, a declined capability that starts receiving data reads as active again with the stored decision shown next to it. See <a href="/features/evidence.html#why-a-card-is-empty">Why a card is empty</a> for how this reads on the execution page.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/getting-started.html">Getting started</a>: connect a first suite</li><li><a href="/reference/features.html">All features</a>: every capability and what it needs</li><li><a href="./integrations.html">Integrations</a>: connect the external services some capabilities use</li></ul>',7)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
